insert into public.translations (locale, key, value) values
  ('en', 'expertise.auto', $json$"Adjust my level automatically"$json$::jsonb),
  ('pt-BR', 'expertise.auto', $json$"Ajustar meu nível automaticamente"$json$::jsonb),
  ('es', 'expertise.auto', $json$"Ajustar mi nivel automáticamente"$json$::jsonb),
  ('zh-CN', 'expertise.auto', $json$"自动调整我的级别"$json$::jsonb),
  ('hi', 'expertise.auto', $json$"मेरा स्तर अपने आप समायोजित करें"$json$::jsonb),
  ('ar', 'expertise.auto', $json$"اضبط مستواي تلقائيًا"$json$::jsonb),
  ('fr', 'expertise.auto', $json$"Ajuster mon niveau automatiquement"$json$::jsonb),
  ('ru', 'expertise.auto', $json$"Автоматически подбирать мой уровень"$json$::jsonb),
  ('ja', 'expertise.auto', $json$"レベルを自動で調整する"$json$::jsonb),
  ('de', 'expertise.auto', $json$"Mein Niveau automatisch anpassen"$json$::jsonb),
  ('en', 'expertise.auto.hint', $json$"After enough requests, the Jev moves your level one step up or down based on how the entry gate treated them, tells you in the chat and lets you undo it."$json$::jsonb),
  ('pt-BR', 'expertise.auto.hint', $json$"Depois de pedidos suficientes, o Jev move o seu nível um degrau para cima ou para baixo conforme a portaria tratou esses pedidos, avisa no chat e deixa você desfazer."$json$::jsonb),
  ('es', 'expertise.auto.hint', $json$"Tras suficientes solicitudes, el Jev mueve tu nivel un escalón hacia arriba o abajo según cómo las trató la puerta de entrada, te avisa en el chat y te deja deshacerlo."$json$::jsonb),
  ('zh-CN', 'expertise.auto.hint', $json$"在积累足够的请求后，Jev 会根据入口关卡对这些请求的处理情况，将你的级别上调或下调一级，并在聊天中通知你，你也可以撤销。"$json$::jsonb),
  ('hi', 'expertise.auto.hint', $json$"पर्याप्त अनुरोधों के बाद, Jev एंट्री गेट के व्यवहार के आधार पर आपका स्तर एक कदम ऊपर या नीचे करता है, चैट में बताता है और आपको इसे पूर्ववत करने देता है।"$json$::jsonb),
  ('ar', 'expertise.auto.hint', $json$"بعد عدد كافٍ من الطلبات ينقل Jev مستواك درجة واحدة للأعلى أو للأسفل بحسب تعامل بوابة الدخول معها، ويُخطرك في المحادثة ويتيح لك التراجع."$json$::jsonb),
  ('fr', 'expertise.auto.hint', $json$"Après suffisamment de requêtes, le Jev monte ou descend votre niveau d'un cran selon le traitement de la porte d'entrée, vous prévient dans le chat et vous laisse annuler."$json$::jsonb),
  ('ru', 'expertise.auto.hint', $json$"После достаточного числа запросов Jev повышает или понижает ваш уровень на одну ступень в зависимости от того, как их обработал входной шлюз, сообщает об этом в чате и позволяет отменить."$json$::jsonb),
  ('ja', 'expertise.auto.hint', $json$"十分な数のリクエストのあと、入口ゲートの扱いに応じて Jev がレベルを1段階上げ下げし、チャットで知らせ、元に戻せます。"$json$::jsonb),
  ('de', 'expertise.auto.hint', $json$"Nach genügend Anfragen stuft der Jev Ihr Niveau je nach Bewertung durch das Eingangstor um eine Stufe hoch oder runter, sagt es im Chat und lässt Sie es rückgängig machen."$json$::jsonb),
  ('en', 'expertise.auto.notice', $json$"The Jev adjusted your level from {from} to {to} based on your recent requests. To undo it, use Undo on the Profile page or Ctrl+K."$json$::jsonb),
  ('pt-BR', 'expertise.auto.notice', $json$"O Jev ajustou o seu nível de {from} para {to} com base nos seus pedidos recentes. Para desfazer, use Desfazer na página Perfil ou o Ctrl+K."$json$::jsonb),
  ('es', 'expertise.auto.notice', $json$"El Jev ajustó tu nivel de {from} a {to} según tus solicitudes recientes. Para deshacerlo, usa Deshacer en la página Perfil o Ctrl+K."$json$::jsonb),
  ('zh-CN', 'expertise.auto.notice', $json$"Jev 根据你最近的请求，将你的级别从 {from} 调整为 {to}。如需撤销，请在“个人资料”页面点击“撤销”，或使用 Ctrl+K。"$json$::jsonb),
  ('hi', 'expertise.auto.notice', $json$"Jev ने आपके हाल के अनुरोधों के आधार पर आपका स्तर {from} से {to} कर दिया। पूर्ववत करने के लिए प्रोफ़ाइल पेज पर “पूर्ववत करें” या Ctrl+K का उपयोग करें।"$json$::jsonb),
  ('ar', 'expertise.auto.notice', $json$"عدّل Jev مستواك من {from} إلى {to} استنادًا إلى طلباتك الأخيرة. للتراجع استخدم «تراجع» في صفحة الملف الشخصي أو Ctrl+K."$json$::jsonb),
  ('fr', 'expertise.auto.notice', $json$"Le Jev a ajusté votre niveau de {from} à {to} d'après vos requêtes récentes. Pour annuler, utilisez Annuler sur la page Profil ou Ctrl+K."$json$::jsonb),
  ('ru', 'expertise.auto.notice', $json$"Jev изменил ваш уровень с {from} на {to} по вашим недавним запросам. Чтобы отменить, нажмите «Отменить» на странице профиля или используйте Ctrl+K."$json$::jsonb),
  ('ja', 'expertise.auto.notice', $json$"最近のリクエストに基づき、Jev がレベルを {from} から {to} に調整しました。元に戻すには、プロフィールページの「元に戻す」か Ctrl+K を使ってください。"$json$::jsonb),
  ('de', 'expertise.auto.notice', $json$"Der Jev hat Ihr Niveau anhand Ihrer letzten Anfragen von {from} auf {to} angepasst. Zum Rückgängigmachen nutzen Sie „Rückgängig“ auf der Profilseite oder Strg+K."$json$::jsonb),
